import { translate, resolveLanguage, type MessageValues } from "./localize.ts";
import { loadSnapshot, saveSnapshot, snapshot } from "./cache.ts";
import type {
  CardConfig,
  HomeAssistant,
  PanelState,
  ZoneProperties,
  ZoneConfiguration,
  MapConfiguration,
  ScalarConfiguration,
} from "./types.ts";
import {
  decodeMask,
  decodeTargets,
  SCALAR_CONTROLS,
  SPECIAL_MAPS,
} from "./protocol.ts";
type Result = ZoneConfiguration | MapConfiguration | ScalarConfiguration;
export class Fp2Client {
  // Remember only messages generated by this client so language switches never
  // rewrite device status strings or user-defined entity names.
  private messages = new Map<string, { key: string; values: MessageValues }>();
  private t(key: string, values: MessageValues = {}) {
    const text = translate(
      key,
      resolveLanguage(this.config, this.hass),
      values,
    );
    this.messages.set(text, { key, values });
    return text;
  }
  localizeMessage(text: string) {
    const message = this.messages.get(text);
    return message ? this.t(message.key, message.values) : text;
  }

  private hass?: HomeAssistant;
  private unsubscribe?: () => void;
  private subscribing = false;
  private unsubscribeCache?: () => void;
  private cacheSubscribing = false;
  private disposed = false;
  private started = false;
  private config: CardConfig;
  private configurationChanged = false;
  private setupReply: Record<string, string> = {};
  private statusPending = false;
  private lastStatusAt = 0;
  private queue: Promise<unknown> = Promise.resolve();
  private timer: ReturnType<typeof setInterval>;
  private prefix: string;
  private servicePrefix: string;
  private node: string;
  private onChange: (state: PanelState) => void;
  state: PanelState = {
    zones: {},
    specialMaps: {},
    scalars: {},
    occupancy: {},
    zoneNames: {},
    room: "unknown",
    traffic: "unknown",
    deviceFresh: false,
    targets: null,
    learningStatus: "unknown",
    autoEdgeCandidate: null,
    configurationStatus: "unknown",
    frames: { valid: "unknown", rejected: "unknown" },
    illuminance: "unknown",
    busy: false,
    progress: null,
    notice: null,
    events: [],
  };
  constructor(config: CardConfig, onChange: (state: PanelState) => void) {
    this.config = config;
    this.prefix = config.entity_prefix ?? "fp2";
    this.servicePrefix = config.service_prefix ?? "fp2";
    this.node = config.node ?? "fp2";
    this.onChange = onChange;
    this.timer = setInterval(() => {
      if (this.hass) {
        this.ingest();
        if (
          !this.config.read_only &&
          !this.state.busy &&
          this.unresolvedLearning() &&
          Date.now() - this.lastStatusAt >= 2000
        )
          void this.refreshStatus();
      }
    }, 1000);
  }
  private entity(domain: string, suffix: string) {
    return this.hass?.states[`${domain}.${this.prefix}_${suffix}`];
  }
  private text(suffix: string) {
    return (
      this.setupReply[suffix] ??
      this.entity("sensor", suffix)?.state ??
      "unknown"
    );
  }
  private emit() {
    if (this.state.cacheError)
      this.state.cacheError = this.localizeMessage(this.state.cacheError);
    if (this.state.notice)
      this.state.notice.message = this.localizeMessage(
        this.state.notice.message,
      );
    if (this.state.progress)
      this.state.progress.label = this.localizeMessage(
        this.state.progress.label,
      );
    if (!this.disposed) this.onChange({ ...this.state });
  }
  attach(hass: HomeAssistant): void {
    if (this.disposed) return;
    this.hass = hass;
    this.ingest();
    if (!this.unsubscribe && !this.subscribing && !this.disposed) {
      this.subscribing = true;
      void hass.connection
        .subscribeEvents((event) => {
          if (this.disposed) return;
          const d = event.data;
          if (d?.node !== this.node || d?.source !== "radar_uart") return;
          try {
            const items = decodeTargets(d.payload_hex);
            if (items.length !== Number(d.count)) return;
            this.state.targets = {
              receivedAt: Date.now(),
              sequence: d.sequence,
              count: items.length,
              items,
            };
            this.emit();
          } catch {
            /* Malformed telemetry never replaces the last valid snapshot. */
          }
        }, "esphome.fp2_targets")
        .then((unsub) => {
          this.subscribing = false;
          if (this.disposed) unsub();
          else this.unsubscribe = unsub;
        })
        .catch(() => {
          this.subscribing = false;
        });
    }
    if (!this.unsubscribeCache && !this.cacheSubscribing) {
      this.cacheSubscribing = true;
      void hass.connection
        .subscribeEvents((event) => {
          if (
            event.data?.url_path ===
            (this.config.cache_dashboard ?? "fp2-cache")
          )
            void this.loadCache();
        }, "lovelace_updated")
        .then((unsub) => {
          this.cacheSubscribing = false;
          if (this.disposed) unsub();
          else this.unsubscribeCache = unsub;
        })
        .catch(() => {
          this.cacheSubscribing = false;
        });
    }
    if (!this.started) {
      this.started = true;
      void this.loadCache();
    }
  }
  private acceptReply(result: any) {
    const reply = result?.response ?? result;
    if (!reply || typeof reply !== "object") return;
    for (const key of [
      "configuration_status",
      "learning_status",
      "auto_edge_candidate",
    ])
      if (typeof reply[key] === "string") this.setupReply[key] = reply[key];
    if (typeof reply.configuration === "string")
      this.setupReply.radar_configuration = reply.configuration;
    this.ingest();
  }
  async refreshStatus() {
    if (
      this.config.read_only ||
      !this.hass ||
      this.disposed ||
      this.statusPending
    )
      return;
    this.statusPending = true;
    this.lastStatusAt = Date.now();
    try {
      this.acceptReply(
        await this.hass.callWS({
          type: "call_service",
          domain: "esphome",
          service: `${this.servicePrefix}_fp2_read_configuration`,
          service_data: { attribute_id: 0, zone_id: 0 },
          return_response: true,
        }),
      );
    } catch {
      /* Optional local status; never retry mutations. */
    } finally {
      this.statusPending = false;
    }
  }
  private async loadCache() {
    try {
      const cached = await loadSnapshot(
        this.hass!,
        this.config.cache_dashboard ?? "fp2-cache",
        this.node,
        this.prefix,
      );
      if (this.disposed) return;
      if (cached) {
        this.state.cacheError = undefined;
        for (const key of ["zones", "specialMaps", "scalars"] as const)
          for (const [id, item] of Object.entries(cached[key]))
            if (!(this.state[key] as any)[id]?.fresh)
              (this.state[key] as any)[id] = item;
        this.state.cacheSavedAt = cached.savedAt;
      } else
        this.state.cacheError = this.t(
          "No saved configuration. Read it from the radar.",
        );
    } catch {
      this.state.cacheError = this.t("Could not load the saved configuration");
    }
    this.emit();
  }
  private async persistCache() {
    if (!this.hass || !this.configurationChanged || this.disposed) return;
    this.configurationChanged = false;
    const value = snapshot(this.state, this.node, this.prefix);
    if (
      Object.keys(value.zones).length !== 30 ||
      Object.keys(value.specialMaps).length !== 3 ||
      Object.keys(value.scalars).length !== 4
    )
      return;
    try {
      await saveSnapshot(
        this.hass,
        this.config.cache_dashboard ?? "fp2-cache",
        value,
      );
      this.state.cacheSavedAt = value.savedAt;
      this.state.cacheError = undefined;
    } catch {
      this.state.cacheError = this.t(
        "Configuration read, but saving to HA failed. Refresh again.",
      );
    }
  }
  dispose() {
    this.disposed = true;
    clearInterval(this.timer);
    this.unsubscribe?.();
    this.unsubscribeCache?.();
  }
  private ingest() {
    this.state.room =
      this.entity("binary_sensor", "room_presence")?.state ?? "unknown";
    this.state.traffic =
      this.entity("binary_sensor", "radar_traffic")?.state ?? "unknown";
    for (let id = 1; id <= 30; id++) {
      const e = this.entity("binary_sensor", `native_zone_${id}_occupancy`);
      this.state.occupancy[id] = e?.state ?? "unknown";
      const name = String(
        e?.attributes.friendly_name ?? this.t("Zone {id}", { id: id }),
      );
      this.state.zoneNames[id] = new RegExp(
        `(?:^| )Native zone ${id} occupancy$`,
        "i",
      ).test(name)
        ? this.t("Zone {id}", { id: id })
        : name;
    }
    this.state.configurationStatus = this.text("configuration_status");
    this.state.learningStatus = this.text("learning_status");
    const candidate = this.text("auto_edge_candidate");
    try {
      decodeMask(candidate);
      this.state.autoEdgeCandidate = candidate;
    } catch {
      this.state.autoEdgeCandidate = null;
    }
    this.state.frames = {
      valid: this.text("valid_radar_frames"),
      rejected: this.text("rejected_radar_frames"),
    };
    this.state.illuminance = this.text("research_illuminance");
    // Availability is a device state, not the age of an optional diagnostic counter.
    // Radar/occupancy watchdogs invalidate these entities; timestamps cross clocks.
    this.state.deviceFresh =
      this.hass?.connection.connected !== false &&
      this.state.traffic === "on" &&
      ["on", "off"].includes(this.state.room);
    this.emit();
  }
  private serialize<T>(fn: () => Promise<T>): Promise<T> {
    const result = this.queue.then(async () => {
      if (this.disposed) throw new Error(this.t("Client disposed"));
      this.state.busy = true;
      this.emit();
      try {
        return await fn();
      } catch (e) {
        this.state.notice = {
          kind: "error",
          message: e instanceof Error ? e.message : String(e),
        };
        throw e;
      } finally {
        await this.persistCache();
        this.state.busy = false;
        this.emit();
      }
    });
    this.queue = result.catch(() => {});
    return result;
  }
  private unresolvedLearning() {
    return /awaiting completion|outcome unknown/.test(
      this.text("learning_status"),
    );
  }
  private async call(action: string, data: Record<string, unknown>) {
    if (this.config.read_only)
      throw new Error(this.t("This card is read-only"));
    if (this.disposed) throw new Error(this.t("Client disposed"));
    if (this.unresolvedLearning())
      throw new Error(this.t("Learning is not complete; commands are paused"));
    if (!this.hass) throw new Error(this.t("Home Assistant unavailable"));
    if (action === "read_configuration") {
      this.acceptReply(
        await this.hass.callWS({
          type: "call_service",
          domain: "esphome",
          service: `${this.servicePrefix}_fp2_${action}`,
          service_data: data,
          return_response: true,
        }),
      );
    } else
      await this.hass.callService(
        "esphome",
        `${this.servicePrefix}_fp2_${action}`,
        data,
      );
  }
  private async until<T>(
    read: () => T | undefined,
    timeout = 7500,
  ): Promise<T> {
    const started = Date.now();
    while (!this.disposed && Date.now() - started < timeout) {
      const value = read();
      if (value !== undefined) return value;
      await new Promise((r) => setTimeout(r, 50));
    }
    throw new Error(this.t("No fresh confirmed radar read-back"));
  }
  private parse(): Result | undefined {
    try {
      const x = JSON.parse(this.text("radar_configuration"));
      if (
        x.source !== "radar_ram" ||
        !Number.isInteger(x.observed_ms) ||
        x.observed_ms < 0 ||
        x.observed_ms > 0xffffffff
      )
        return;
      if (x.kind === "zone") {
        if (
          !Number.isInteger(x.id) ||
          x.id < 1 ||
          x.id > 30 ||
          !["active_raw", "sensitivity", "type", "close_away_raw"].every((k) =>
            Number.isInteger(x[k]),
          )
        )
          return;
        decodeMask(x.mask);
      } else if (x.kind === "map") {
        if (!SPECIAL_MAPS.some((s) => s.attribute === x.attribute)) return;
        decodeMask(x.mask);
      } else if (x.kind === "scalar") {
        if (
          !SCALAR_CONTROLS.some((s) => s.attribute === x.attribute) ||
          !Number.isInteger(x.raw) ||
          x.raw < 0 ||
          x.raw > 0xffffffff ||
          !Number.isInteger(x.wire) ||
          x.wire !== (x.attribute === 0x106 ? 3 - x.raw : x.raw)
        )
          return;
      } else return;
      return { ...x, fresh: false, seenAt: Date.now() };
    } catch {
      return;
    }
  }
  private async read(attribute: number, id = 0): Promise<Result> {
    let lastError: unknown;
    for (let attempt = 0; attempt < 2; attempt++) {
      if (this.disposed) throw new Error(this.t("Client disposed"));
      if (this.unresolvedLearning())
        throw new Error(this.t("Learning is not complete"));
      const previous = this.parse()?.observed_ms;
      try {
        await this.call("read_configuration", {
          attribute_id: attribute,
          zone_id: id,
        });
        const result = await this.until(() => {
          const x = this.parse();
          if (!x || x.observed_ms === previous) return;
          if (
            id
              ? x.kind !== "zone" || x.id !== id
              : x.kind === "zone" || x.attribute !== attribute
          )
            return;
          return x;
        });
        result.fresh = true;
        this.configurationChanged = true;
        if (result.kind === "zone") this.state.zones[result.id] = result;
        else if (result.kind === "map")
          this.state.specialMaps[result.attribute] = result;
        else this.state.scalars[result.attribute] = result;
        this.emit();
        return result;
      } catch (e) {
        lastError = e;
      }
    }
    throw lastError;
  }
  refreshAll(): Promise<void> {
    return this.serialize(async () => {
      const jobs = [
        ...Array.from({ length: 30 }, (_, i) => ({ attr: 0x114, id: i + 1 })),
        ...SCALAR_CONTROLS.map((s) => ({ attr: s.attribute, id: 0 })),
        ...SPECIAL_MAPS.map((s) => ({ attr: s.attribute, id: 0 })),
      ];
      let failures = 0;
      try {
        for (let i = 0; i < jobs.length; i++) {
          if (this.disposed || this.unresolvedLearning()) break;
          this.state.progress = {
            done: i,
            total: 37,
            label: this.t("Reading configuration"),
          };
          this.emit();
          try {
            await this.read(jobs[i].attr, jobs[i].id);
          } catch {
            failures++;
          }
          if (this.disposed) break;
        }
        if (failures)
          throw new Error(
            this.t("Could not read {count} sections", { count: failures }),
          );
      } finally {
        this.state.progress = null;
      }
    });
  }
  readZone(id: number) {
    this.zoneId(id);
    return this.serialize(() => this.read(0x114, id));
  }
  private zoneId(id: number) {
    if (!Number.isInteger(id) || id < 1 || id > 30)
      throw new Error(this.t("Zone must be 1\u202630"));
  }
  private async write(
    action: string,
    data: Record<string, unknown>,
    attribute: number,
    id: number,
    verify: (result: Result) => boolean,
  ) {
    await this.call(action, data);
    const started = Date.now();
    while (Date.now() - started < 3000) {
      await this.refreshStatus();
      const status = this.text("configuration_status");
      if (/reject|fail/.test(status)) throw new Error(status);
      if (/acknowledged|unconfirmed/.test(status)) break;
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
    const result = await this.read(attribute, id);
    if (!verify(result))
      throw new Error(this.t("Radar read-back does not match the change"));
    this.state.notice = {
      kind: "success",
      message: this.t("Change confirmed by reading radar RAM"),
    };
    return result;
  }
  private checkedMask(mask: string) {
    try {
      return decodeMask(mask);
    } catch (error) {
      if (error instanceof Error) throw new Error(this.t(error.message));
      throw error;
    }
  }
  saveZone(id: number, mask: string, properties?: ZoneProperties) {
    this.zoneId(id);
    if (properties) this.validateProperties(properties);
    if (!this.checkedMask(mask).some(Boolean))
      throw new Error(this.t("Use deleteZone for empty geometry"));
    return this.serialize(async () => {
      await this.write(
        "zone_mask",
        { zone_id: id, mask_hex: mask },
        0x114,
        id,
        (x) =>
          x.kind === "zone" &&
          x.mask.toLowerCase() === mask.toLowerCase() &&
          x.active_raw !== 0,
      );
      if (properties) await this.properties(id, properties);
    });
  }
  deleteZone(id: number) {
    this.zoneId(id);
    const mask = "0".repeat(80);
    return this.serialize(() =>
      this.write(
        "zone_mask",
        { zone_id: id, mask_hex: mask },
        0x114,
        id,
        (x) => x.kind === "zone" && x.mask === mask && x.active_raw === 0,
      ),
    );
  }
  saveSpecialMap(attribute: number, mask: string) {
    this.checkedMask(mask);
    if (!SPECIAL_MAPS.some((s) => s.attribute === attribute))
      throw new Error(this.t("Unsupported map"));
    return this.serialize(() =>
      this.write(
        "special_map",
        { attribute_id: attribute, mask_hex: mask },
        attribute,
        0,
        (x) => x.kind === "map" && x.mask.toLowerCase() === mask.toLowerCase(),
      ),
    );
  }
  saveScalar(attribute: number, value: number) {
    const control = SCALAR_CONTROLS.find((s) => s.attribute === attribute);
    if (
      !control ||
      !Number.isInteger(value) ||
      value < control.min ||
      value > control.max
    )
      throw new Error(this.t("Unsupported scalar value"));
    return this.serialize(() =>
      this.write(
        "scalar",
        { attribute_id: attribute, value },
        attribute,
        0,
        (x) => x.kind === "scalar" && x.wire === value,
      ),
    );
  }
  private validateProperties(props: ZoneProperties) {
    for (const [key, min, max] of [
      ["sensitivity", 1, 3],
      ["type", 0, 39],
      ["close_away_value", 0, 1],
    ] as const) {
      const value = props[key];
      if (
        value !== undefined &&
        (!Number.isInteger(value) || value < min || value > max)
      )
        throw new Error(this.t("Unsupported zone property"));
    }
  }
  private async properties(id: number, props: ZoneProperties) {
    this.validateProperties(props);
    const entries = [
      { key: "sensitivity", attr: 0x151, min: 1, max: 3 },
      { key: "type", attr: 0x152, min: 0, max: 39 },
      { key: "close_away_value", attr: 0x153, min: 0, max: 1 },
    ] as const;
    for (const e of entries) {
      const value = props[e.key];
      if (
        value !== undefined &&
        (!Number.isInteger(value) || value < e.min || value > e.max)
      )
        throw new Error(this.t("Unsupported zone property"));
    }
    for (const e of entries) {
      const value = props[e.key];
      if (value === undefined) continue;
      await this.write(
        "zone_property",
        { attribute_id: e.attr, zone_id: id, value },
        0x114,
        id,
        (x) =>
          x.kind === "zone" &&
          (e.key === "close_away_value"
            ? x.close_away_raw === (value === 0 ? 1 : 0)
            : x[e.key] === value),
      );
    }
  }
  saveZoneProperties(id: number, props: ZoneProperties) {
    this.zoneId(id);
    return this.serialize(() => this.properties(id, props));
  }
  renameZone(id: number, name: string) {
    this.zoneId(id);
    if (!name.trim()) throw new Error(this.t("Name required"));
    return this.serialize(async () => {
      if (!this.hass) throw new Error(this.t("Home Assistant unavailable"));
      await this.hass.callWS({
        type: "config/entity_registry/update",
        entity_id: `binary_sensor.${this.prefix}_native_zone_${id}_occupancy`,
        name: name.trim(),
      });
    });
  }
  startLearning(attribute: number) {
    if (attribute !== 0x113 && attribute !== 0x150)
      throw new Error(this.t("Unsupported learning action"));
    return this.serialize(async () => {
      await this.call("start_learning", { attribute_id: attribute });
      await this.refreshStatus();
      this.state.notice = {
        kind: "info",
        message: this.t(
          "Start requested. ACK and learning completion appear separately in the radar status.",
        ),
      };
    });
  }
}
